const qnet='https://www.q-net.or.kr/';
const table=(caption,heads,rows)=>`<table class="practical-comparison" role="table"><caption>${caption}</caption><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td data-label="${heads[i]}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const source=(url,label)=>`<p class="editorial-note">근거 <a href="${url.replaceAll('&','&amp;')}" target="_blank" rel="noopener">${label}</a> · 2026년 11월 9일 해당 항목 확인. 학습 일정·계산 예·상담표는 편집자가 만든 예시이며 공식 문제나 채점표가 아닙니다.</p>`;
module.exports=[
 {slug:'측량기능사-실기-장비-학원',description:'측량기능사 실기 학원을 고를 때 레벨·토털스테이션 개인 실습과 답안 기록을 비교하세요. 공식 공개문제의 작업 구분과 기초 레벨 계산 예시, 수업 상담표를 정리했습니다.',
  html:`<h2>실기 학원은 장비 시연보다 내가 끝까지 해보는 수업인지 봅니다</h2><p>측량기능사 실기 학원을 찾는 초보자라면 레벨과 토털스테이션을 모두 직접 다루고, 관측값을 기록해 답안 계산까지 해보는지 확인하세요. 공식 종목 안내와 공개문제는 두 측량 작업을 구분합니다. 장비가 있다는 설명만으로 개인 실습시간이나 답안 피드백이 보장되지는 않습니다.</p><p>2026년 11월 9일 확인한 Q-Net 공개문제는 토털스테이션 작업 50분과 레벨 작업 40분을 안내합니다. 연습할 때도 두 작업을 따로 끝내는 데 그치지 말고 준비·관측·기록·계산 과정에서 어디에 시간이 걸렸는지 적어보세요. 이 글은 공개문제의 문항·도면·답안지를 복제하지 않으며, 응시 회차에 바뀐 안내가 있다면 공식 자료를 우선합니다.</p>${table('측량 실기 수업 상담에 쓸 비교표',['확인 항목','구체적으로 물을 질문','받아 적을 답'],[['개인 실습','한 반 정원과 장비 수, 개인이 직접 조작하는 시간은 어떻게 되나요?','인원·장비·개인 시간'],['작업 범위','레벨과 토털스테이션을 모두 연습하나요?','각 작업의 수업·보강 범위'],['답안 피드백','제가 기록하고 계산한 과정의 오류도 확인해 주나요?','조작·기록·계산별 피드백'],['환경·안전','야외 실습 일정과 안전 지도는 어떻게 운영하나요?','기상 변경·지도·보호구 안내'],['총비용','보충 연습·장비·교재 비용이 수강료에 포함되나요?','포함 항목과 별도 금액']])}<h3>기초 레벨 계산을 숫자로 확인하는 연습</h3><p>다음은 공개문제와 무관하게 만든 단순 기초 연습입니다. 기준점 높이를 100.000m, 후시를 1.245m, 다음 점의 전시를 0.985m로 가정합니다. 여기서는 기계고식의 덧셈·뺄셈과 단위만 연습하며, 실제 시험의 왕복 관측·이기점·특수 조건 전체를 다루는 예제는 아닙니다.</p>${table('편집자가 만든 기초 계산 예시',['계산 단계','식','결과'],[['기계고','100.000 + 1.245','101.245m'],['다음 점의 높이','101.245 - 0.985','100.260m'],['높이차 교차 확인','1.245 - 0.985','+0.260m']])}<p>결과 숫자가 틀렸을 때는 원래 기록한 값이 맞는지, 더하고 뺄 대상을 바꾸지 않았는지, 단위를 혼용했는지 순서대로 살펴봅니다. 계산만 맞는다고 장비 조작과 현장 측량 능력이 입증되지는 않습니다. 실제 관측은 안전한 교육 환경에서 지도받고 공식 요구 조건에 맞춰 연습하세요.</p>${source(qnet+'crf005.do?id=crf00503&gSite=Q&jmCd=6980','Q-Net 측량기능사 종목 안내·현재 게시된 공개문제')}`,
  faq:[['측량기능사 실기는 온라인 강의만으로 준비할 수 있나요?','계산 설명을 듣는 것과 장비를 조작하며 관측·기록하는 것은 다릅니다. 본인이 직접 실습할 환경과 피드백을 먼저 확보하세요. 온라인 강의만으로 실기 준비가 충분하다고 보장할 수는 없습니다.'],['수강료가 저렴한 측량 학원을 고르면 되나요?','개인 실습시간, 두 장비의 연습 범위, 답안 피드백과 보강 비용을 같은 항목으로 비교하세요. 표시 수강료가 낮아도 장비 연습이나 보강이 별도이면 전체 비용과 준비 범위가 달라질 수 있습니다.']]},
 {slug:'산업안전기사-산업안전산업기사-응시자격-비교',description:'산업안전기사와 산업안전산업기사 응시자격을 학력·실무경력·기능사 취득 후 경력별 비교표로 정리했습니다. 비전공자의 확인 순서와 학원 상담 전 준비할 서류를 살펴보세요.',
  html:`<h2>기사와 산업기사 응시자격은 내 학력·경력 경로부터 비교합니다</h2><p>산업안전기사가 목표라고 산업안전산업기사를 반드시 먼저 취득해야 하는 것은 아닙니다. Q-Net의 기사·산업기사 응시자격 중 본인이 충족할 수 있는 경로를 먼저 확인하세요. 아래 표는 대표 경로를 비교한 것이며 모든 경로를 나열하거나 개인별 인정 여부를 대신 심사하는 표가 아닙니다.</p>${table('기사와 산업기사 대표 응시 경로 비교',['비교할 경로','기사','산업기사'],[['관련 학력','관련학과 대학 졸업 등 또는 졸업예정 경로','관련학과 2·3년제 전문대학 졸업 등 또는 졸업예정 경로 등'],['실무경력만으로 검토','동일·유사 직무분야 4년 이상','동일·유사 직무분야 2년 이상'],['기능사 취득 후 검토','취득 후 동일·유사 분야 실무 3년 이상','취득 후 동일·유사 분야 실무 1년 이상'],['최종 확인','본인 학력·자격·업무 자료로 서류심사','본인 학력·자격·업무 자료로 서류심사']])}<p>비전공자가 경력 경로만 검토하는 가상 사례를 생각해 보겠습니다. 동일·유사 분야에 해당할 수 있는 실무 3년을 증명할 자료가 있더라도 기사의 경력 단독 경로인 4년과는 차이가 있습니다. 산업기사의 기간 요건을 검토할 수는 있지만, 실제 직무 인정과 기준일·증빙 심사는 별도로 확인해야 합니다. ‘회사를 3년 다녔다’는 사실만으로 어느 시험이든 바로 응시할 수 있다고 결론 내리지 마세요.</p><h3>응시자격을 만들어 준다는 상담 전에 확인할 것</h3><p>교육기관이 설명하는 준비 경로와 시행기관의 자격 인정은 다른 단계입니다. 강의 수강을 신청한 것, 교육을 마친 것, 학점·학력이 공식 인정된 것, 시험 응시자격 심사가 완료된 것을 나눠 확인합니다. 특정 기관에 비용을 내면 개인의 학력·경력 인정까지 보장된다는 표현을 그대로 받아들이지 마세요.</p><ul><li>졸업·재학 증명과 성적 자료, 보유 자격 취득일, 회사별 근무기간·실제 담당 업무를 준비합니다.</li><li>Q-Net 자가진단에서 어떤 경로를 검토했는지 기록하고 필요한 서류와 제출 기한을 확인합니다.</li><li>학과·직무 인정이 애매하면 계약 전에 공단에 본인 상황을 구체적으로 문의합니다. 자가진단은 최종 서류심사 결과가 아닙니다.</li><li>상담 기관에는 학습 기간뿐 아니라 인정 절차·예상 완료 시점·비용·취소 조건을 서면으로 요청합니다.</li></ul>${source(qnet+'crf006.do?id=crf00603&gSite=Q&gradeType=30&tabIdx=2','Q-Net 기사 응시자격 안내')}<p><a href="${qnet}crf006.do?id=crf00603&amp;gSite=Q&amp;gradeType=31&amp;tabIdx=3" target="_blank" rel="noopener">산업기사 응시자격 원문</a>도 함께 대조하세요. 기준일과 제출 서류는 응시 회차 안내를 따릅니다.</p>`,
  faq:[['비전공자는 산업안전기사에 응시할 수 없나요?','비전공이라는 이유만으로 모든 경로가 막히는 것은 아닙니다. 동일·유사 분야 실무경력 등 다른 인정 경로를 검토할 수 있지만 실제 업무와 제출 서류를 확인해야 합니다. 학과명이나 재직기간 한 항목만으로 판단하지 마세요.'],['학원에서 응시 가능하다고 하면 바로 접수해도 되나요?','교육기관의 설명과 Q-Net의 최종 서류심사는 구분해야 합니다. 본인이 검토한 응시 경로와 학력·경력 자료, 기준일과 제출 기한을 공식 안내로 대조하세요.']]},
 {slug:'지게차운전기능사-필기-공부법',title:'지게차운전기능사 필기 공부법과 초보자 복습 순서',description:'지게차운전기능사 필기의 공식 과목·문항 수를 확인하고 초보자 2주 복습 계획과 하루 60분 학습 예시, 오답 분류표로 공부 순서를 잡는 방법입니다.',
  html:`<h2>처음이라면 진단 문제부터 풀고 복습 범위를 정합니다</h2><p>지게차 필기 공부법을 찾는 초보자라면 문제집을 처음부터 여러 번 읽기 전에 짧은 진단 문제를 풀어보세요. 모르는 용어가 많은지, 안전 조건을 놓치는지, CBT 화면이 낯선지에 따라 다음 공부가 달라집니다. Q-Net은 필기를 객관식 60문항·60분으로, 과목을 주행·화물 적재·운반·하역·안전관리로 안내합니다.</p><p>아래 2주 계획은 편집자가 제안하는 복습 예시이지 합격 기간을 보장하는 일정이 아닙니다. 기초가 부족하거나 학습시간을 확보하기 어렵다면 각 단계를 늘려 잡으세요. 문제집의 복원 문항을 공식 공개 기출과 동일한 자료라고 표시하지 않습니다.</p>${table('초보자를 위한 2주 복습 계획 예시',['기간','할 일','다음 단계로 넘어갈 기준'],[['1~3일','출제기준과 교재 목차를 맞추고 용어·진단 오답 분류','틀린 이유를 모르는 항목이 무엇인지 파악'],['4~7일','과목별 문제를 풀고 장비·작업 조건을 짧게 설명','답 번호 없이 정답 이유와 다른 보기의 문제점을 말하기'],['8~10일','과목을 섞어 풀고 반복 실수만 재복습','해설을 본 직후와 다음 날의 결과를 구분'],['11~14일','60분 제한으로 연습하고 CBT 조작도 따로 확인','시간 부족·지식 오류·화면 조작 오류를 나눠 보완']])}<h3>하루 60분을 쓸 수 있다면 이렇게 나눠보세요</h3><p>이전 오답을 다시 설명하는 데 15분, 오늘 정한 범위의 학습에 25분, 새 문제를 풀고 근거를 확인하는 데 10분, 다음 날 다시 볼 항목을 정리하는 데 10분을 배분할 수 있습니다. 실제 가능한 시간에 맞춰 조절하되 해설을 읽고 고개를 끄덕인 것과 혼자 설명할 수 있는 것을 구분하세요.</p>${table('점수 옆에 남기는 오답 분류',['분류','기록할 질문','다음 복습'],[['용어','부품·장비·작업 용어 중 무엇을 몰랐나?','해당 용어의 뜻과 역할을 한 문장으로 정리'],['조건','문제의 작업 환경·상태 중 무엇을 빠뜨렸나?','빠뜨린 조건에 표시하고 문장을 다시 읽기'],['단위·계산','주어진 단위와 구하려는 값을 섞지 않았나?','식과 단위를 함께 적어 확인'],['화면·시간','문제 이동·표시·제출 과정이 낯설었나?','지식 복습과 별도로 공식 CBT 체험']])}<p><a href="/큐넷-CBT-시험-체험-답안제출/">큐넷 공식 CBT 체험에서 확인할 화면 조작</a>을 함께 살펴보세요. 필기 문제풀이로 실제 장비의 운전 요령을 임의로 연습하지 않습니다. 조종 훈련과 안전교육, 실기·면허 절차는 별도로 준비해야 합니다.</p>${source(qnet+'crf005.do?id=crf00503&gSite=Q&jmCd=7875','Q-Net 지게차운전기능사 필기 과목·시험 방식·2025~2027년 출제기준')}`,
  faq:[['지게차 필기를 2주만 공부하면 합격할 수 있나요?','위 일정은 공부 순서를 설명하는 예시입니다. 기초지식·하루 학습시간·오답 원인에 따라 필요한 기간이 달라집니다. 정해진 날짜만 채우기보다 같은 오류가 반복되는지와 제한시간 안에 근거를 설명할 수 있는지를 확인하세요.'],['문제의 정답 번호만 외워도 되나요?','문제의 조건과 보기 순서가 바뀌면 번호 암기는 도움이 되지 않을 수 있습니다. 정답 이유와 다른 보기가 맞지 않는 이유를 자신의 말로 설명하고 다음 날 다시 확인해 보세요.']]}
];
